def addOperators(num: str, target: int) -> list[str]:
    res = []
    def backtrack(idx, prev_val, curr_val, path):
        if idx == len(num):
            if curr_val == target:
                res.append(path)
            return
        for j in range(idx + 1, len(num) + 1):
            if j > idx + 1 and num[idx] == '0': break
            sub = num[idx:j]
            val = int(sub)
            if idx == 0:
                backtrack(j, val, val, sub)
            else:
                backtrack(j, val, curr_val + val, path + '+' + sub)
                backtrack(j, -val, curr_val - val, path + '-' + sub)
                backtrack(j, prev_val * val, curr_val - prev_val + prev_val * val, path + '*' + sub)
    backtrack(0, 0, 0, '')
    return sorted(res)

